let busy=false,queued=null,editError='';const format=(k,v)=>['melt','blend','depth'].includes(k)?Math.round(v*100)+'%':k==='output'||k==='level'?Number(v).toFixed(1)+' dB':['cutoff','highpass','lowpass'].includes(k)?Math.round(v)+' Hz':k==='rate'?Number(v).toFixed(2)+' Hz':['sweep','envelope'].includes(k)?Number(v).toFixed(2)+' oct':k==='attack'||k==='release'?v+' ms':Number(v).toFixed(2)+'×';
function sync(){const s=runtime.settings();syncPlayground(s);card.querySelector('#waspSecondWarning').hidden=!s.routes[1].enabled;card.dataset.enabled=String(s.enabled);const button=card.querySelector('#waspPower');button.textContent=s.enabled?'WASP ON':'WASP OFF';button.setAttribute('aria-pressed',String(s.enabled));for(const el of card.querySelectorAll('[data-wasp]')){const row=el.closest('[data-wasp-route]'),v=(row?s.routes[Number(row.dataset.waspRoute)]:el.closest('[data-wasp-filter]')?s.filter:s)[el.dataset.wasp];if(el.type==='checkbox'||document.activeElement!==el){if(el.type==='checkbox')el.checked=v;else el.value=String(v);}const out=el.closest('label')?.querySelector('output');if(out)out.textContent=format(el.dataset.wasp,v);}for(const row of card.querySelectorAll('[data-wasp-route]'))row.dataset.active=String(s.routes[Number(row.dataset.waspRoute)].enabled);const d=runtime.diagnostics();card.querySelector('#waspStatus').textContent=editError||d.error?editError||d.error:s.enabled?(d.worklets?'Nest active · ':'Armed · start audio to hear Wasp · ')+d.activeRoutes+' of 1 source active':d.pendingRetirement?'Returning to hard bypass…':'Hard bypass · no Wasp DSP';}
async function edit(label,fn){if(busy){queued={label,fn};return;}try{if(root.mygrainCardHistory?.busy||root.mygrainSongBeta?.busy||root.mygrainSongBeta?.playing||stateSaveSuspended)throw Error('Finish the current edit or stop Song playback before editing Wasp.');busy=true;editError='';const action=async()=>{const s=runtime.settings();fn(s);if(s.enabled||s.playground.enabled)await ensurePatchZipAudioReady();await runtime.restore(s);saveState();};if(root.mygrainCardHistory)await root.mygrainCardHistory.runDraftEdit(label,action);else await action();return true;}catch(e){editError=e.message;card.querySelector('#waspStatus').textContent=e.message;setStatus(e.message,'error');return false;}finally{busy=false;sync();if(queued){const next=queued;queued=null;queueMicrotask(()=>edit(next.label,next.fn));}}}
