function drawPlayground(canvas,curve){if(root.mygrainDisplay&&!root.mygrainDisplay.canDraw(canvas,()=>drawPlayground(canvas,curve)))return;const ctx=canvas.getContext('2d'),w=canvas.width,h=canvas.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#080e19';ctx.fillRect(0,0,w,h);ctx.strokeStyle='#ffffff12';ctx.lineWidth=1;const pg=runtime.settings().playground,lane=pg.modulation[canvas.closest('[data-playground-lane]')?.dataset.playgroundLane]||DSP.rateMod(pg.rateMod),window=DSP.curveWindow(lane,pg.tempo),grid=lane.snap?window.grid:1/8;for(let t=grid;t<1&&t/grid<512;t+=grid){ctx.beginPath();ctx.moveTo(t*w,0);ctx.lineTo(t*w,h);ctx.stroke();}ctx.strokeStyle='#ffffff40';ctx.strokeRect(.5,.5,w-1,h-1);for(let i=1;i<4;i++){ctx.beginPath();ctx.moveTo(0,i*h/4);ctx.lineTo(w,i*h/4);ctx.stroke();}const color=getComputedStyle(canvas.closest('.wasp-pg-lane')).getPropertyValue('--pg-accent').trim()||'#59e4dc';ctx.beginPath();for(let i=0;i<64;i++){const x=i*w/63,y=(1-curve[i])*h/2;i?ctx.lineTo(x,y):ctx.moveTo(x,y);}ctx.strokeStyle=color;ctx.lineWidth=3;ctx.stroke();ctx.lineTo(w,h);ctx.lineTo(0,h);ctx.closePath();ctx.fillStyle=color+'18';ctx.fill();}
