let lastPlaygroundPreset='';
function syncPlayground(s){root.mygrainEffectOutput?.syncUi();const pg=s.playground;const presetId=root.MygrainPlaygroundPresets.match(pg),preset=root.MygrainPlaygroundPresets.list.find(p=>p.id===presetId);if(presetId)lastPlaygroundPreset=presetId;playground.querySelector('#playgroundPreset').value=presetId;playground.querySelector('#playgroundPresetDescription').textContent=preset?preset.description+' Power, input, main tempo and kick routing stay unchanged.':"Custom patch · choose a preset to configure all three lanes. Power, input, main tempo and kick routing stay unchanged. Turn Playground on to hear it.";const section=playground;section.dataset.enabled=String(pg.enabled);section.querySelector('.wasp-pg-power span').textContent=pg.enabled?'PLAYGROUND ON':'PLAYGROUND OFF';for(const el of section.querySelectorAll('[data-playground]')){const lane=el.closest('[data-playground-lane]')?.dataset.playgroundLane,key=el.dataset.playground,v=lane&&['source','amount','clock','hz','bpm','beats','multiplier','timing','snap','snapTiming','phaseOffset','interpolation'].includes(key)?(pg.modulation[lane][key]??(key==='phaseOffset'?0:key==='interpolation'?'auto':undefined)):(pg[key]??(key==='input'?'all':key==='glide'?.35:['motion','mix'].includes(key)?1:undefined));if(el.type==='checkbox'||document.activeElement!==el){if(el.type==='checkbox')el.checked=v;else el.value=String(v);}const out=el.closest('label')?.querySelector('output');if(out)out.textContent=key==='q'?Number(v).toFixed(2):key==='amount'?(v>=0?'+':'')+Math.round(v*100)+'%':['cutoff','resonant'].includes(key)?Math.round(v)+' Hz':key==='hz'||key==='rate'?Number(v).toFixed(2)+' Hz':key==='bpm'?Math.round(v)+' BPM':['attack','release','glide'].includes(key)?Number(v).toFixed(key==='glide'?2:1)+' ms':['motion','mix'].includes(key)?Math.round(v*100)+'%':key==='phaseOffset'?Number(v).toFixed(3)+' cycles':Number(v).toFixed(1)+'×';}for(const row of section.querySelectorAll('[data-playground-lane]')){const key=row.dataset.playgroundLane,lane=pg.modulation[key],drawn=lane.source==='drawn';row.querySelector('.wasp-pg-draw').hidden=!drawn;for(const button of section.querySelectorAll('[data-playground-draw="'+key+'"]'))button.setAttribute('aria-expanded',String(drawn));row.querySelector('.wasp-pg-draw-open').textContent=drawn?'✎ Edit drawn curve':'✎ Draw a curve';const view=DSP.curveWindow(lane,pg.tempo),number=v=>Number(v.toFixed(4)).toString();row.querySelector('.wasp-pg-clock-status').textContent='FULL DRAWING WINDOW = 1 LOOP · '+number(view.seconds)+' s · '+number(view.beats)+' beats · '+number(view.hz)+' Hz'+(lane.snap?' · grid '+number(view.gridBeats)+' beats'+(view.grid>=1?' · grid ≥ loop: draw between the two endpoints':''):' · free drawing');row.querySelector('.wasp-pg-time-axis').replaceChildren(...[0,.25,.5,.75,1].map(fraction=>{const tick=document.createElement('span');tick.textContent=number(view.beats*fraction)+' beats';tick.title=number(view.seconds*fraction)+' seconds';return tick;}));row.querySelector('canvas').setAttribute('aria-description','One complete loop: '+number(view.seconds)+' seconds, '+number(view.beats)+' beats. '+(view.grid>=1?'Grid is at least one loop; both endpoints remain drawable.':'Snap grid follows the current loop timing.'));for(const input of row.querySelectorAll('[data-playground]')){const k=input.dataset.playground;if(['hz','bpm','beats','multiplier','timing'].includes(k))input.closest('label').hidden=k==='hz'?lane.clock!=='hz':k==='bpm'?lane.clock!=='bpm':lane.clock==='hz';}drawPlayground(row.querySelector('canvas'),lane.curve);}syncRate(pg);const d=runtime.diagnostics();section.querySelector('.wasp-pg-status').textContent=!pg.enabled?'OFF · hard bypass · no Playground DSP or modulation taps':!d.playgroundStages?'ARMED · start audio to hear the Playground':`ON · Input: ${pg.input==='DAW'?'VST3 FX':pg.input?names(pg.input):'All'} · ${pg.slope/6} poles · ${d.playgroundTaps||0} detection taps`;}
async function applyPlaygroundPreset(id){
 const preset=root.MygrainPlaygroundPresets.list.find(p=>p.id===id);if(!preset)return;
 const changed=await edit('Playground preset · '+preset.name,s=>{const {enabled,tempo,routeKick,input}=s.playground;s.playground={...root.MygrainPlaygroundPresets.get(id),enabled,tempo,routeKick,...(input?{input}:{})};});
 if(changed)for(const row of playground.querySelectorAll('[data-playground-lane]')){row.querySelector('[data-pg-mode]').value=preset.shape==='freehand'?'freehand':'blocks';row.querySelector('[data-pg-block-shape]').value=preset.shape==='freehand'?'square':preset.shape;}
}
